def write_records(self) -> str:
    database_name = self._get_param("DatabaseName")
    table_name = self._get_param("TableName")
    records = self._get_param("Records")
    self.timestreamwrite_backend.write_records(database_name, table_name, records)
    # Return the expected response format with the number of records ingested
    return json.dumps({
        'RecordsIngested': {
            'Total': len(records),
            'MemoryStore': len(records),  # All records go to memory store first
            'MagneticStore': 0  # Records are moved to magnetic store later
        }
    })

